package org.bukkit; import org.bukkit.plugin.*; import org.bukkit.inventory.*; public class Bukkit {public static PluginManager manager;public static Inventory created;public static java.util.Map<Integer,ItemStack> slots;public static PluginManager getPluginManager(){return manager;}public static Inventory createInventory(InventoryHolder h,int n,String title){slots=new java.util.HashMap<>();created=new Inventory(){public void setItem(int slot,ItemStack item){slots.put(slot,item);}public InventoryHolder getHolder(){return h;}};return created;}}
